14	@RestControllerAdvice
15	public class GlobalExceptionHandler {
16	
17	    /**
18	     * 错误响应体：code 为机器可区分错误码，message 为人读描述；
19	     * details 为可选结构化明细（如解决门禁未完成项、未解除阻塞的事件键列表），无则 null。
20	     */
21	    public record ErrorBody(String code, String message, Object details) {
22	    }
23	
24	    @ExceptionHandler(ApiException.class)
25	    public ResponseEntity<ErrorBody> handleApi(ApiException ex) {
26	        return ResponseEntity.status(ex.status())
27	                .body(new ErrorBody(ex.code(), ex.getMessage(), ex.details()));
28	    }
29	
30	    @ExceptionHandler({HttpMessageNotReadableException.class, MissingRequestHeaderException.class})
