package com.example.starter.incident;

import java.time.Instant;

/**
 * 处置任务实体，对应 incident_tasks 表。
 * (incidentId, taskKey) 唯一，同键同内容幂等，同键不同内容冲突；
 * 每事件至多 20 个任务。doneBy/doneAt 仅 DONE 有值，cancelledBy/cancelledAt 仅 CANCELLED 有值。
 * version 初始 1，配置择一前置组、完成、取消成功各加一，用于依赖图判定的乐观锁。
 * 时间均为 UTC。
 */
public record IncidentTask(
        long id,
        long incidentId,
        String taskKey,
        String groupCode,
        String title,
        TaskStatus status,
        String createdBy,
        String doneBy,
        Instant doneAt,
        String cancelledBy,
        Instant cancelledAt,
        int version,
        Instant createdAt,
        Instant updatedAt) {

    /**
     * 判断两条任务的业务内容是否一致（用于 taskKey 幂等比对；阻塞事件集合另行比对）。
     */
    public boolean sameContent(String groupCode, String title) {
        return this.groupCode.equals(groupCode) && this.title.equals(title);
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 择一前置组实体，对应 task_prerequisite_groups 表。
 * 每任务 1~3 组，配置替换时整组重建，仅 OPEN 任务可配置；
 * 完成判定要求每组至少一个 DONE 成员。selectedMemberId 为任务完成时冻结的
 * 选中依据成员（该组 DONE 成员中完整任务标识字典序最小者），未完成为空，冻结后不再变更。
 * 时间均为 UTC。
 */
public record TaskPrerequisiteGroup(
        long id,
        long taskId,
        int groupNo,
        Long selectedMemberId,
        Instant createdAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 择一前置组成员实体，对应 task_prerequisite_members 表。
 * 每组 2~5 个成员，以事件号与任务号标识，可跨事件；
 * 仅 DONE 满足前置，CANCELLED 不满足，全部取消仍阻塞。
 * expectedTaskVersion 为配置时声明的成员任务期望版本，
 * 与成员当前版本不一致时配置失败（409）。时间均为 UTC。
 */
public record TaskPrerequisiteMember(
        long id,
        long groupId,
        long memberIncidentId,
        long memberTaskId,
        int expectedTaskVersion,
        Instant createdAt) {
}

