```java
private List<PrerequisiteGroupView> prerequisiteGroups(long taskId) {
    List<MemberDetail> details = prerequisites.listMemberDetails(taskId);
    Map<Integer, List<MemberDetail>> byGroup = new LinkedHashMap<>();
    for (MemberDetail d : details) byGroup.computeIfAbsent(d.groupNo(), k -> new ArrayList<>()).add(d);
    // also need selectedMemberId per group — details carry it
    List<PrerequisiteGroupView> groups = new ArrayList<>();
    for (var entry : byGroup.entrySet()) {
        List<PrerequisiteMemberView> members = entry.getValue().stream().map(this::toMemberView).toList();
        Long selectedId = entry.getValue().get(0).selectedMemberId();
        PrerequisiteMemberView selected = null;
        if (selectedId != null) {
            for (int i = 0; i < entry.getValue().size(); i++) {
                if (entry.getValue().get(i).memberId() == selectedId) { selected = members.get(i); break; }
            }
        }
        groups.add(new PrerequisiteGroupView(entry.getKey(), members, selected));
    }
    return groups;
}

private PrerequisiteMemberView toMemberView(MemberDetail d) {
    return new PrerequisiteMemberView(d.incidentKey(), d.taskKey(), d.taskStatus(),
            d.expectedTaskVersion(), TaskStatus.DONE.name().equals(d.taskStatus()));
}
