private void freezeSelections(long taskId) {
    List<MemberDetail> details = prerequisites.listMemberDetails(taskId);
    Map<Long, List<MemberDetail>> byGroup = new LinkedHashMap<>(); // groupId -> members, already sorted by (incidentKey, taskKey)
    for (MemberDetail d : details) byGroup.computeIfAbsent(d.groupId(), k -> new ArrayList<>()).add(d);
