                .filter(d -> TaskStatus.DONE.name().equals(d.taskStatus()))
                .findFirst()  // 已按事件号、任务号字典序排序
                .orElseThrow(() -> new IllegalStateException("完成门禁已通过但组内无 DONE 成员"));
        prerequisites.markSelected(entry.getKey(), selected.memberId());
    }
}
